import heapq

def match(orders):
    buy_heap = []   # (-price, seq, id) for resting buy orders
    sell_heap = []  # (price, seq, id) for resting sell orders
    seq_counter = 0
    book = {}  # id -> {'side','price','qty','seq','active'}
    trades = []

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            if side == 'buy':
                o_price, oseq, oid2 = opp_heap[0]
            else:
                neg_price, oseq, oid2 = opp_heap[0]
                o_price = neg_price

            info = book.get(oid2)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            if typ == 'market':
                cond = True
            else:
                if side == 'buy':
                    cond = o_price <= price
                else:
                    cond = o_price >= price

            if not cond:
                break

            trade_qty = min(remaining, info['qty'])

            if side == 'buy':
                trades.append([oid, oid2, o_price, trade_qty])
            else:
                trades.append([oid2, oid, o_price, trade_qty])

            info['qty'] -= trade_qty
            remaining -= trade_qty

            if info['qty'] == 0:
                info['active'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'seq': seq_counter,
                'active': True
            }
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))
            seq_counter += 1
        # ioc/market remainder is discarded, nothing to do

    return trades

